mapper.select:
select min(id)
from b_customize_upload_data_smy
where receive_date = #{date,jdbcType=VARCHAR}
  and api_code = #{apiCode,jdbcType=VARCHAR}
  and status = 1
  and sync_status = 0

select *
from b_customize_upload_data_smy
where receive_date = #{date,jdbcType=VARCHAR}
  and api_code = #{apiCode,jdbcType=VARCHAR}
  and status = 1
  and sync_status = 0

    and id > #{minId,jdbcType=BIGINT}

order by id
limit #{limit,jdbcType=INTEGER}
